import{_ as a,o as e,c as s,ai as o}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"文件与报表","description":"上传文件、让 Bot 处理表格和文档、生成 Excel / PPT / PDF 报表的实用方法。","frontmatter":{"related":["/roles/data-reports","/automation/daily-briefing","/basics/cloud-computer"],"title":"文件与报表","description":"上传文件、让 Bot 处理表格和文档、生成 Excel / PPT / PDF 报表的实用方法。","section":"basics","order":5,"tags":["基础","文件","报表","Excel"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/computer-and-apps"],"wordCount":482,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"文件与报表 | WANGXXXL"}],["meta",{"property":"og:description","content":"上传文件、让 Bot 处理表格和文档、生成 Excel / PPT / PDF 报表的实用方法。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/basics/files-reports"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/basics-files-reports-208f278e6d.png"}],["meta",{"property":"og:image:alt","content":"文件与报表 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"文件与报表 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"上传文件、让 Bot 处理表格和文档、生成 Excel / PPT / PDF 报表的实用方法。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/basics-files-reports-208f278e6d.png"}],["meta",{"name":"twitter:image:alt","content":"文件与报表 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/basics/files-reports"}]]},"headers":[],"relativePath":"basics/files-reports.md","filePath":"basics/files-reports.md","lastUpdated":1792485206000}'),n={name:"basics/files-reports.md"};function i(l,t,p,c,r,d){return e(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="文件与报表" tabindex="-1">文件与报表 <a class="header-anchor" href="#文件与报表" aria-label="Permalink to &quot;文件与报表&quot;">​</a></h1><p>很多人用 Grok Bot 的第一个&quot;真香&quot;时刻，是把一份乱糟糟的表格丢给它，几分钟后拿回一份整理好的报表。因为它有自己的电脑，可以真正运行代码处理数据，而不是&quot;估算&quot;。</p><h2 id="给它文件" tabindex="-1">给它文件 <a class="header-anchor" href="#给它文件" aria-label="Permalink to &quot;给它文件&quot;">​</a></h2><ul><li><strong>直接拖进对话</strong>：图片、PDF、Office 文档、CSV、JSON、音视频、代码文件等常见格式都支持。单条消息的附件数量和单个文件大小有上限，以官方最新说明为准。</li><li><strong>给链接</strong>：Bot 能在云电脑上打开的页面，或已连接网盘里的文件。</li><li><strong>让它自己去取</strong>：比如&quot;从邮箱里下载上周的对账单附件&quot;。</li></ul><div class="tip custom-block"><p class="custom-block-title">告诉它每个文件是什么</p><p>多个附件时，说清楚每个文件的用途，能避免它搞混。</p></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PDF 是我们签的服务协议，Excel 是本月的结算明细。</span></span>
<span class="line"><span>请按协议核对明细，每一条不符合协议的记录都标出对应条款编号，</span></span>
<span class="line"><span>最后给我一个新的 Excel 和一段简短总结。不要修改原文件。</span></span></code></pre></div><h2 id="让它产出文件" tabindex="-1">让它产出文件 <a class="header-anchor" href="#让它产出文件" aria-label="Permalink to &quot;让它产出文件&quot;">​</a></h2><p>Bot 可以在云电脑上生成各种格式：Excel、CSV、Word、PPT、PDF、图表图片等。生成后会以文件卡片的形式出现在对话里，可以预览、保存，或者直接回复修改意见。</p><p>一个说清楚的报表需求，大概长这样：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用附件里的销售明细做一份月度报表（Excel）：</span></span>
<span class="line"><span>- Sheet1&quot;汇总&quot;：按渠道汇总金额、订单数、客单价，按金额降序；</span></span>
<span class="line"><span>- Sheet2&quot;趋势&quot;：按周的金额折线图；</span></span>
<span class="line"><span>- Sheet3&quot;明细&quot;：原始数据，加一列&quot;是否异常&quot;（金额超过均值 3 倍标记为是）；</span></span>
<span class="line"><span>文件名：月度报表_2026-09.xlsx。做完后用三句话告诉我最值得注意的变化。</span></span></code></pre></div><h2 id="改-而不是重做" tabindex="-1">改，而不是重做 <a class="header-anchor" href="#改-而不是重做" aria-label="Permalink to &quot;改，而不是重做&quot;">​</a></h2><p>拿到报表后有修改意见，让它在原文件上改：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在刚才那个报表上改：汇总表加一列&quot;环比&quot;，图表换成柱状图。还是同一个文件名，覆盖保存。</span></span></code></pre></div><p>这样不会冒出一堆&quot;报表_v2_最终版_真的最终版&quot;。</p><h2 id="让结果可核查" tabindex="-1">让结果可核查 <a class="header-anchor" href="#让结果可核查" aria-label="Permalink to &quot;让结果可核查&quot;">​</a></h2><p>重要报表，让它附上&quot;审计线索&quot;：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在报表最后加一页&quot;说明&quot;：数据来源文件、处理步骤、剔除了哪些记录及原因、</span></span>
<span class="line"><span>有哪些地方你不确定。</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">截图不等于数据</p><p>对于变化很快的数据（比如实时后台），截图只能说明某一刻的状态。需要准确数字时，让它导出原始数据，而不是看图读数。</p></div><h2 id="文件整理习惯" tabindex="-1">文件整理习惯 <a class="header-anchor" href="#文件整理习惯" aria-label="Permalink to &quot;文件整理习惯&quot;">​</a></h2><ul><li>让 Bot 把项目文件放在 <code>/workspace/项目名/</code> 下，命名带日期。</li><li>敏感文件用完让它删除。云电脑上的文件你所有 Bot 都能看到。</li><li>最终版发到对话里或存到你的网盘，别只留在云电脑上。</li></ul>`,20)])])}const g=a(n,[["render",i]]);export{h as __pageData,g as default};
